class Solution {
    public int jump(int[] nums) {
        int curRight = 0;
        int nextRight = 0;
        int res = 0;
        for(int i = 0;i<nums.length-1;i++){
            nextRight = Math.max(nextRight,nums[i]+i);
            if(curRight==i){
                curRight = nextRight;
                res++;
            }
        }
        return res;
    }
}
